python3 -c "from pathlib import Path; p=Path('programs/task-75bea1de.py'); p.write_text('def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    r0,c0=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==2)
    # The 2 sends straight rays in four directions. At an 8 it passes
    # through the opening(s), while the open segment immediately before
    # the barrier is filled across; continue along each opening.
    active={(r0,c0)}
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        r,c=r0+dr,c0+dc
        while 0<=r<h and 0<=c<w and grid[r][c]!=8:
            out[r][c]=2; r+=dr; c+=dc
        if not (0<=r<h and 0<=c<w): continue
        if dr: holes=[j for j,v in enumerate(grid[r]) if v!=8]
        else: holes=[i for i in range(h) if grid[i][c]!=8]
        # line ray meets a wall; fill the previous open row/column and
        # transmit the beam through the wall openings.
        if dr:
            prev=r-dr
            if 0<=prev<h:
                for j in range(w):
                    if grid[prev][j]!=8: out[prev][j]=2
            for j in holes:
                if grid[r][j]==0: out[r][j]=2
        else:
            prev=c-dc
            if 0<=prev<w:
                for i in range(h):
                    if grid[i][prev]!=8: out[i][prev]=2
            for i in holes:
                if grid[i][c]==0: out[i][c]=2
    # Along transmission openings the rays continue perpendicular from
    # each opened spot, illuminating clear cells until the next 8 barrier.
