 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sr, sc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)
    # The source beam travels vertically. At each horizontal wall, continue
    # through the gap(s) and fill the clear row on the approach side from the
    # incoming column to the wall's outermost gap.
    current = {sc}
    for r in range(sr + 1, h):
        if 8 not in grid[r]:
            for c in current:
                if grid[r][c] == 0:
                    out[r][c] = 2
            continue
        gaps = [c for c, value in enumerate(grid[r]) if value == 0]
        if not gaps:
            break
        hit = [c for c in current if grid[r][c] == 8]
        if not hit:
            continue
        incoming = min(hit, key=lambda c: (abs(c - sc), c))
        lo, hi = min(incoming, min(gaps)), max(incoming, max(gaps))
        for c in range(lo, hi + 1):
            if grid[r - 1][c] == 0:
                out[r - 1][c] = 2
        for c in gaps:
            out[r][c] = 2
        current = set(gaps)
    out[sr][sc] = 2
