 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal rows of 8 are fences. A vertical beam hitting a fence
    # splits through all gaps; each gap starts a fresh downward beam. The
    # blank strip above each fence is filled between its extreme openings.
    bands = [r for r, row in enumerate(grid) if 8 in row]
    active = {next((c for r in range(h) for c in range(w) if grid[r][c] == 2), 0)}
    for r in bands:
        gaps = [c for c, value in enumerate(grid[r]) if value == 0]
        if not gaps:
            continue
        if not any(grid[r][c] == 8 for c in active):
            continue
        for c in gaps:
            out[r][c] = 2
        lo, hi = min(gaps), max(gaps)
        if r > 0:
            for c in range(lo, hi + 1):
                if grid[r - 1][c] == 0:
                    out[r - 1][c] = 2
        active = set(gaps)
        end = next((rr for rr in bands if rr > r), h)
        for c in gaps:
            for rr in range(r + 1, end):
                if grid[rr][c] == 0:
                    out[rr][c] = 2
    sr, sc = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)
    for r in range(sr + 1, bands[0] if bands else h):
        if grid[r][sc] == 0:
            out[r][sc] = 2
    return out
