        out[r][c] = 2
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 8:
            out[rr][cc] = 2
            r, c = rr, cc
            rr += dr
            cc += dc
        if not (0 <= rr < h and 0 <= cc < w):
            break
        state = (rr, cc, dr, dc)
