        hits = [c for c in active if grid[r][c] == 8]
        if not gaps or not hits:
            continue
        # Connect to the closest aperture(s) in the clear lane above.
        targets = set()
        for hit in hits:
            distance = min(abs(hit - gap) for gap in gaps)
            targets.update(gap for gap in gaps if abs(hit - gap) == distance)
        if r > 0:
            if len(gaps) == 1:
                for c in range(w):
                    if grid[r - 1][c] == 0:
